from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/items/")
async def read_items(
    strange_header: str | None = Header(default=None, convert_underscores=True),
):
    return {"strange_header": strange_header}

client = TestClient(app)

def test_underscore_header_rejected():
    # When convert_underscores=True, 'strange_header' should NOT be accepted.
    # Only 'strange-header' should be accepted.
    response = client.get("/items/", headers={"strange_header": "FastAPI test"})
    assert response.json() == {"strange_header": None}, f"Expected None, got {response.json()}"

def test_hyphen_header_accepted():
    # When convert_underscores=True, 'strange-header' SHOULD be accepted.
    response = client.get("/items/", headers={"strange-header": "FastAPI test"})
    assert response.json() == {"strange_header": "FastAPI test"}, f"Expected 'FastAPI test', got {response.json()}"

if __name__ == "__main__":
    try:
        test_underscore_header_rejected()
        print("test_underscore_header_rejected passed")
    except AssertionError as e:
        print(f"test_underscore_header_rejected failed: {e}")

    try:
        test_hyphen_header_accepted()
        print("test_hyphen_header_accepted passed")
    except AssertionError as e:
        print(f"test_hyphen_header_accepted failed: {e}")
EOF
